// Zoom to Bounding Box — Interaction, route: ref
// Source: zoom-to-bounding-box
//
// Self-contained: every local import is inlined below. Requires only d3, geojson, react, topojson-client, topojson-specification, us-atlas, world-atlas.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { feature, mesh } from 'topojson-client';
import countries110m from 'world-atlas/countries-110m.json';
import statesUs from 'us-atlas/states-10m.json';
import type { GeometryCollection, Topology } from 'topojson-specification';
import type { Feature, FeatureCollection, Geometry, MultiLineString } from 'geojson';
import { useEffect, useMemo, useRef } from 'react';
import * as d3 from 'd3';

// ---- inlined from geo ----
// The atlases ship untyped JSON. One cast per topology at this boundary keeps every
// consumer strict, and converting here means each chart does not re-derive the same
// geometry at module load.

type Named = { name: string };
type NamedFeature = Feature<Geometry, Named>;

const world = countries110m as unknown as Topology<{
  countries: GeometryCollection<Named>;
  land: GeometryCollection;
}>;

const us = statesUs as unknown as Topology<{
  states: GeometryCollection<Named>;
  nation: GeometryCollection;
}>;

const worldCountries = feature(
  world,
  world.objects.countries
) as FeatureCollection<Geometry, Named>;

const worldLand = feature(world, world.objects.land) as FeatureCollection<Geometry>;

/** Shared borders only, so neighbouring outlines are stroked once instead of twice. */
const worldBorders = mesh(
  world,
  world.objects.countries,
  (a, b) => a !== b
) as MultiLineString;

const usNation = feature(us, us.objects.nation) as FeatureCollection<Geometry>;

const usStateBorders = mesh(
  us,
  us.objects.states,
  (a, b) => a !== b
) as MultiLineString;

/**
 * The 50 states plus DC. geoAlbersUsa cannot project FIPS ids of 60 and above
 * (territories) and returns null for them, which becomes a NaN centroid downstream.
 * Use this rather than the raw collection for anything Albers-projected.
 */
const usStates: NamedFeature[] = (
  feature(us, us.objects.states) as FeatureCollection<Geometry, Named>
).features.filter((d) => Number(d.id) < 60);

const usStatesCollection: FeatureCollection<Geometry, Named> = {
  type: 'FeatureCollection',
  features: usStates
};

/**
 * FNV-1a over an id, run through the murmur3 finalizer. Two-character FIPS ids barely
 * differ, and without the finalizer they map to a near-constant. Returns [0, 1).
 * Charts use it to synthesize per-region values deterministically instead of fetching.
 */
function hashUnit(id: string, salt = 0): number {
  let h = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i++) {
    h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 2246822507);
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

const MARGIN = { top: 28, right: 8, bottom: 8, left: 8 };
const MAX_SCALE = 8;
const DURATION = 750;

export default function ZoomToBoundingBox({ width }: { width: number }) {
  const svgRef = useRef<SVGSVGElement | null>(null);
  const height = Math.round(width * 0.626);

  // fitExtent rather than fitSize so projected coordinates already carry the margin
  // offset — the zoomed group then needs no translate, and path.bounds and d3.pointer
  // agree on one coordinate space.
  const path = useMemo(
    () =>
      d3.geoPath(
        d3
          .geoAlbersUsa()
          .fitExtent(
            [
              [MARGIN.left, MARGIN.top],
              [Math.max(width - MARGIN.right, MARGIN.left + 1), Math.max(height - MARGIN.bottom, MARGIN.top + 1)]
            ],
            usStatesCollection
          )
      ),
    [width, height]
  );

  useEffect(() => {
    const node = svgRef.current;
    if (!node || width === 0) return;

    const svg = d3.select(node);
    svg.selectAll('*').remove();

    svg
      .append('text')
      .attr('class', 'axis')
      .attr('x', MARGIN.left + 6)
      .attr('y', 16)
      .text(
        width >= 560
          ? 'Click a state to zoom to its bounding box. Click the background to reset.'
          : 'Click a state to zoom.'
      );

    const g = svg.append('g');

    const states = g
      .append('g')
      .attr('cursor', 'pointer')
      .selectAll<SVGPathElement, NamedFeature>('path')
      .data(usStates)
      .join('path')
      .attr('fill', 'var(--muted)')
      .attr('d', (d) => path(d) ?? '');

    states.append('title').text((d) => d.properties.name);

    g.append('path')
      .attr('fill', 'none')
      .attr('stroke', 'var(--panel)')
      .attr('stroke-linejoin', 'round')
      .attr('d', path(usStateBorders) ?? '');

    const zoom = d3
      .zoom<SVGSVGElement, unknown>()
      .scaleExtent([1, MAX_SCALE])
      .on('zoom', (event: d3.D3ZoomEvent<SVGSVGElement, unknown>) => {
        g.attr('transform', event.transform.toString());
        g.attr('stroke-width', 1 / event.transform.k);
      });

    const clicked = (event: PointerEvent, d: NamedFeature) => {
      event.stopPropagation();
      const [[x0, y0], [x1, y1]] = path.bounds(d);
      states.attr('fill', 'var(--muted)');
      d3.select(event.currentTarget as SVGPathElement).attr('fill', 'var(--accent)');

      // 0.9 leaves a margin of empty space around the fitted bounding box.
      const scale = Math.min(
        MAX_SCALE,
        0.9 / Math.max((x1 - x0) / width, (y1 - y0) / height)
      );

      svg
        .transition()
        .duration(DURATION)
        .call(
          zoom.transform,
          d3.zoomIdentity
            .translate(width / 2, height / 2)
            .scale(scale)
            .translate(-(x0 + x1) / 2, -(y0 + y1) / 2),
          d3.pointer(event, node)
        );
    };

    const reset = () => {
      states.attr('fill', 'var(--muted)');
      svg
        .transition()
        .duration(DURATION)
        .call(
          zoom.transform,
          d3.zoomIdentity,
          d3.zoomTransform(node).invert([width / 2, height / 2])
        );
    };

    states.on('click', clicked);
    svg.on('click', reset).call(zoom);

    return () => {
      svg.interrupt();
      svg.on('.zoom', null).on('click', null);
      svg.selectAll('*').remove();
    };
  }, [width, height, path]);

  if (width === 0) return null;

  return (
    <svg
      ref={svgRef}
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      style={{ cursor: 'grab', touchAction: 'none' }}
      role="img"
      aria-label="Map of United States. Click a state to zoom to its bounding box, or scroll and drag to pan and zoom."
    />
  );
}
